#!/usr/bin/env python3
"""mk_sched.py: web/fx/sched.js = the harness' per-pass schedule of fx0 and fx1 (FITTED, not derived: the pass cost in ISR ticks depends on the CPU).
Per pass: PT = music time (s) of the frame record, ORD = order at the loop top; fx0: F = [753f] (ISR ticks since the order reset) read at the LUT build; fx1: TK = ISR ticks since the previous loop top (TK[0] = 7 ticks before the first top; ticks between consecutive loop tops; ADV = fill advance per plane (offset at the next top minus this one: the pending size as actually consumed, includes the tick-between-reads cases); TM = further ticks before the offset table is built (phases read there))."""
import numpy as np, json
f0 = np.load('re/oracle0c/fx0.npy', allow_pickle=True); f1 = np.load('re/oracle1c/fx1.npy', allow_pickle=True)
fl = {(e[4], e[0]): e[2] for e in json.load(open('re/oracle1d/fill1.json')) if e[1] == 1}   # fill COUNT read at 0x25e8d.. (oracle1d = oracle1c + read hooks, same ticks)
r = lambda a: [round(float(x), 4) for x in a]
irq = [int(f['tick'][23]) for f in f1]; mq = [int(f['mid'][6]) for f in f1]   # ISR count at the loop top / when the offset table is built (0x25b3c; 0..2 ticks later)
S = dict(fx0=dict(PT=r(f['mt'] for f in f0), ORD=[int(f['tick'][19]) for f in f0], F=[int(f['mid'][1]) for f in f0]),
         fx1=dict(PT=r(f['mt'] for f in f1), ORD=[int(f['tick'][24]) for f in f1], TK=[7] + [irq[i] - irq[i - 1] for i in range(1, len(irq))], TM=[mq[i] - irq[i] for i in range(len(irq))],
                    FILL=[[fl.get((i, k), 0) for k in range(3)] for i in range(len(f1))],
                    ADV=[[int(f1[min(i + 1, len(f1) - 1)]['tick'][13 + k] - f['tick'][13 + k]) if i + 1 < len(f1) else int(f['tick'][10 + k]) for k in range(3)] for i, f in enumerate(f1)]))
open('web/fx/sched.js', 'w').write('// generated by tools/mk_sched.py from re/oracle0c, re/oracle1c: harness per-pass schedule of fx0/fx1 (fitted, machine dependent)\nexport const SCHED = ' + json.dumps(S, separators=(',', ':')) + ';\n')
